-- Seeds the real products table from the static apps/api/src/data/products.json
-- bundle that catalog.ts used to read directly. Generated by a one-off script
-- (scratchpad/generate-products-seed.mjs, not part of the repo) rather than
-- hand-written - 200 rows, split into batches (a single 200-row INSERT hits
-- SQLite's SQLITE_TOOBIG statement-size limit). Preserves id/slug exactly so
-- existing /products/<slug> URLs keep resolving to the same product after
-- this migration. visibility='visible' for every row, matching the
-- storefront's current behavior (every product in the JSON was always shown).
INSERT OR IGNORE INTO products
  (id, sku, slug, name, brand, category, subcategory, price_cents, compare_at_price_cents, final_price_cents, stock, low_stock_threshold, visibility, featured, is_new, is_deal, rating_average, rating_count, details_json, created_at, updated_at)
